  ('strawberry-dream-cake', 'Strawberry Dream Cake', 'cakes', 'Vanilla sponge, fresh strawberries and whipped mascarpone cream.', 'Our most-requested cake. Three layers of light vanilla bean sponge, filled with macerated summer strawberries and a cloud of whipped mascarpone cream, finished with a soft-textured buttercream and a crown of fresh berries.', '["strawberry","sliced","celebration"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":68},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":94},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":126}]'::jsonb, '[{"label":"Vanilla bean sponge","price":0},{"label":"Lemon sponge","price":0},{"label":"Gluten-free vanilla","price":8}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 2, 'Bestseller', true, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#F2E3DC', 0),
