  ('pistachio-rose-cake', 'Pistachio Rose Cake', 'cakes', 'Pistachio sponge, raspberry and a delicate rose buttercream.', 'Our most romantic cake. Toasted pistachio sponge layered with raspberry compote and a softly perfumed rose buttercream, scattered with crushed pistachio and dried petals.', '["pistachio","floral","wedding"]'::jsonb, '[{"id":"6in","label":"6\" round","servings":"8–10 servings","price":74},{"id":"8in","label":"8\" round","servings":"14–18 servings","price":100},{"id":"10in","label":"10\" round","servings":"24–30 servings","price":132}]'::jsonb, '[{"label":"Pistachio sponge","price":0},{"label":"Vanilla sponge","price":0}]'::jsonb, '[{"id":"classic","label":"Classic Sweet Daisy finish","price":0},{"id":"fresh-flowers","label":"Fresh seasonal flowers","price":18},{"id":"gold-leaf","label":"Edible gold leaf accents","price":14},{"id":"berries","label":"Fresh berry crown","price":12}]'::jsonb, true, 3, 'New', false, '[{"label":"Allergens","value":"Contains pistachio, wheat, eggs, dairy."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#E3E5D3', 4),
