  ('sweet-daisy-dessert-box', 'Sweet Daisy Dessert Box', 'treats', 'Mini tarts, macarons, cookies and cake bites to share.', 'A grazing box for gatherings: mini fruit tarts, macarons, brown butter cookies and bite-sized cake squares, arranged by hand and wrapped with ribbon.', '["dessertBox","tart","cookies"]'::jsonb, '[{"id":"small","label":"Petite box","servings":"Serves 4–6","price":48},{"id":"large","label":"Grand box","servings":"Serves 10–12","price":92}]'::jsonb, '[]'::jsonb, '[]'::jsonb, true, 2, 'Gift favourite', false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#EFE5D3', 11),
  ('brown-butter-cookies', 'Brown Butter Cookies', 'treats', 'Chewy brown butter cookies with dark chocolate and sea salt.', 'Thick, chewy cookies made with nutty brown butter, chunks of dark chocolate and a sprinkle of flaky sea salt. Baked fresh every morning.', '["cookies","packaging"]'::jsonb, '[{"id":"box6","label":"Box of 6","servings":"6 cookies","price":18},{"id":"box12","label":"Box of 12","servings":"12 cookies","price":34}]'::jsonb, '[]'::jsonb, '[]'::jsonb, false, 0, null, false, '[{"label":"Allergens","value":"Contains wheat, eggs, dairy. Made in a kitchen that handles nuts."},{"label":"Storage","value":"Keep refrigerated. Serve at room temperature — remove 1 hour before slicing."},{"label":"Best enjoyed","value":"Within 3 days of collection."}]'::jsonb, '#E9DCC8', 12),
